/* @lc app=leetcode id=2573 lang=kotlin */ class Solution { fun fill(s: CharArray, lcp: Array<IntArray>, i: Int, ch: Char) = (i until s.size).forEach { j -> if (lcp[i][j] > 0 && s[j] == '?') s[j] = ch } fun findTheString(lcp: Array<IntArray>): String = lcp.size.let { n -> CharArray(n) { '?' }.let { s -> (0 until n).fold(0) { c, i -> if (s[i] != '?') c else (if (c < 26) fill(s, lcp, i, 'a' + c) else Unit).let { c + 1 } }.let { used -> if (used > 26) "" else Array(n + 1) { IntArray(n + 1) }.let { d -> (n - 1 downTo 0).forEach { i -> (n - 1 downTo 0).forEach { j -> d[i][j] = if (s[i] == s[j]) d[i + 1][j + 1] + 1 else 0 } }.let { if ('?' in s || (0 until n).any { i -> (0 until n).any { j -> d[i][j] != lcp[i][j] } }) "" else String(s) } } } } } }